local a=require("ExcelTool")local b=a.Pack;local c=a.Sub;local d=a.LangGet;local e=a.Dmap;local f=require("Excels.Data.item_definition.skin")local g=f.tb;local h=f.get;g[406604]=b({e[46057],406604,4,75,327,"「あたしとのデート大作戦、またの名をクリスマス遊園地の旅、まもなく始まりまーす！　えへへ、まずは最初のミッション、あたしの手作りチョコクッキー、美味しそうに食べられるかなのコーナー！　はい、あ～ん♪」",200066,2,"deco/character/sigongdongshi_SD",false,false,false,false,false,false,false,"1",false,false,"-100,0,1","80,-80,1",false,"-100,0,1","-100,0,1",false,false,false,false,false,false,false,false,false,false,false,2110,917,388,936,418,2104,2754,936,610,2104,1261,"sigongdongshi_sd"},h)g[406605]=b({e[46057],406605,15,120,328,"「すぅ……はぁ……。この歌は、普通の子な私に、私が持つ特別さに気付かせてくれた人のために、ありったけの想いを込めて書きました。だから……私の気持ち、聴いてください。じゃあ、行くよー！　3、2、1――！」",200066,2,"deco/character/sigongdongshi_OX",false,false,false,false,false,false,false,"1",false,false,"-60,0,1","240,-140,0.94","-100,0,1","-100,0,1","-110,0,1",false,false,false,false,false,false,false,false,false,false,false,2023,891,388,374,238,3026,3071,436,584,2902,1261,"sigongdongshi_ox"},h)g[406606]=b({e[9057],406606,21,20,329,"「雀士さん、お疲れさま！\nはい、はちみつドリンク。疲れによく効くよ！\nあ……うん、これ、あたしがいつも使ってる水筒。おうちで作って、そのまま持ってきたから……。\n気にしないで、よかったらそのまま使って！\n……あ、あの。\n……頑張ってね！ 応援してます！」",200066,2,"deco/character/sigongdongshi_ydh","sigongdongshi_ydh"},h)g[406701]=b({e[35057],406701,false,146,330,false,200067,false,"deco/character/qingluan",302002,60,false,false,false,false,85,"1",false,false,false,false,false,false,false,"150,-20,1",false,"-30,100,1",false,"-30,100,1",false,"-10,60,1","0,60,1","-10,60,1","0,60,1","0,40,1","qingluan"},h)g[406702]=b({e[12057],406702,1,4,331,"「何れにせよ、青き鳥は雲の果てへ帰りゆくであろう。\nその時は、そなたも共に喜んでくれるか？」",200067,1,"deco/character/qingluan_0",302002,60,1,"qingluan_0"},h)g[406703]=b({e[24045],406703,6,70,332,"「律回り歳晩れて氷霜少なし、春人間に到らば草木知る……そなた、このセイランと共に、庭歩きに興じてくれぬか？」",200067,2,"deco/character/406703",false,false,1,false,false,false,false,"1",false,"140,0,0.98","0,0,0.98",false,"0,0,0.98","0,0,0.98","0,0,0.98",1,5520,5000,2974,4677,8000,8500,16000,8000,15000,8000,8000,"qingluan_cj",false,0},h)g[406704]=b({e[17045],406704,2,82,333,"「清冽なる水は身の穢れを祓うが、其の内の卑俗なる欲を洗い流すには至らぬ。\n……そなたが関心を抱いておるのなら、我は構わぬぞ。共に暑気を払うとしよう。」",200067,2,"deco/character/qingluan_xr",false,false,false,false,false,false,false,"",1,2686,5000,1327,2513,4000,8000,8000,8000,18867,8000,8000,"qingluan_xr"},h)g[406801]=b({e[17023],406801,false,147,334,false,200068,false,"deco/character/ruyuecaiyin",302002,60,1,false,false,false,10,"0.98","50,130,1","0,0,0.98","0,0,0.98","0,0,0.98","0,0,0.98","0,0,0.98","-20,0,0.98","20,0,0.98","0,0,0.98",false,false,1864,871,386,1272,798,1609,2584,1272,798,1609,1026},h)g[406802]=b({e[12034],406802,1,4,335,"「今夜の読み聞かせは、『眠り姫』の話にしよっか。\n……ん？ これは、子供のおとぎ話じゃなくて、愛と勇気の物語なの。\n王子のように、茨の道を切り開いて愛する人に会いにいくような、勇敢な人になってもらわないと……。\nえ、先生は何になるの、って？\nふふっ、先生は、王子様を待つお姫様になるわ。\nあんまり長く待たせちゃイ・ヤ・よ♡」",200068,1,"deco/character/ruyuecaiyin_0",302002,60,1,1896,852,392,1189,796,2043,2247,1189,796,2043,1012},h)g[406803]=b({e[21034],406803,4,75,336,"「今日は一日先生のために時間をくれるって言ったのに……。うちの学校だと、授業中にスマホを触った生徒は廊下に立たされるらしいのよね。う～ん、あなたへの罰は何にし・よ・う・か・な～？」",200068,2,"deco/character/406803",false,false,false,false,false,false,false,"1",false,false,false,"0,-100,1",1849,871,398,1073,728,2201,2363,1073,728,2201,1102,1,3319,5000,1614,3031,3333,10000,10000,10000,13000,8000,3333,false,false,0},h)g[406804]=b({e[24034],406804,5,117,337,"「どう？　素敵でしょ、この晴れ着。けど、どうしても動きにくいわね……。ねえ、私を起こしてもらえる？　それとも、一緒に寝ころびたい？」",200068,2,"deco/character/ruyuecaiyin_YD",false,false,false,false,1,false,false,"1",false,"0,120,0.95","-250,120,0.95","240,-140,0.89","-250,120,0.95","-250,120,0.95","-60,60,0.95",2255,1049,398,553,28,2979,3356,592,747,2901,1261,1,1489,5000,733,1293,5333,10000,7500,8000,13000,8000,5333},h)g[406901]=b({e[46057],406901,false,148,338,false,200069,false,"deco/character/weilai",302002,60,1,false,false,false,-22,"1",false,false,false,false,false,false,false,"100,130,1","40,10,1","-50,20,1","40,10,1","-50,20,1",false,"-90,0,1","-40,0,1","-90,0,1","-40,0,1",false,1907,852,386,1044,777,1884,2614,1044,777,1884,1028,"weilai"},h)g[406902]=b({e[11034],406902,1,4,339,"「パラレルワールドって、聞いたことある？\n研究によると、僕たちが何かしらの選択をするたびに、別の世界が誕生するらしいよ。\nだからたまに思うんだ。あの日、ベーカーズをキミにぶつけたのも、ある種の幸運だったんじゃないかって。\n少なくとも、その時に僕達が出会う世界……新たな未来が生まれたってことになるからね。」",200069,1,"deco/character/weilai_0",302002,60,1842,833,392,741,436,2827,2963,741,528,2827,1261,false,false,false,false,false,false,false,false,false,false,false,false,"weilai_0"},h)